// Peer-to-peer networking via PeerJS (WebRTC). The host is authoritative;
// clients send inputs/actions and receive snapshots/events.
const PREFIX = 'opuslethal55-';
const ICE = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun.cloudflare.com:3478' },
    { urls: 'turn:openrelay.metered.ca:80', username: 'openrelayproject', credential: 'openrelayproject' },
    { urls: 'turn:openrelay.metered.ca:443', username: 'openrelayproject', credential: 'openrelayproject' },
  ],
};

export class Net {
  constructor() {
    this.peer = null;
    this.conns = new Map();
    this.hostConn = null;
    this.isHost = false;
    this.online = false;
    this.id = 'solo';
    this.handlers = {};
  }
  on(t, f) { this.handlers[t] = f; }

  _mkPeer(id) {
    // eslint-disable-next-line no-undef
    return id ? new Peer(PREFIX + id, { debug: 0, config: ICE }) : new Peer({ debug: 0, config: ICE });
  }

  host(code) {
    return new Promise((res, rej) => {
      if (typeof Peer === 'undefined') return rej(new Error('PeerJS unavailable'));
      const p = this.peer = this._mkPeer(code);
      const to = setTimeout(() => rej(new Error('Timed out contacting matchmaking server')), 15000);
      p.on('open', (id) => { clearTimeout(to); this.id = id; this.isHost = true; this.online = true; res(id); });
      p.on('error', (e) => { clearTimeout(to); if (!this.online) rej(e); else console.warn('peer error', e); });
      p.on('connection', (c) => this._setup(c));
      p.on('call', (call) => this.handlers.call && this.handlers.call(call));
      p.on('disconnected', () => { try { p.reconnect(); } catch (e) { } });
