// Audio: procedural sound design with Web Audio (HRTF positional), streamed music
// from the three.js example library, and proximity/radio voice chat routing.
import { ASSET_BASES } from './assets.js';

const MUSIC = {
  menu: 'sounds/376737_Skullbeatz___Bad_Cat_Maste.mp3',
  boombox: 'sounds/358232_j_s_song.mp3',
};

export class AudioSys {
  constructor() {
    this.ctx = null;
    this.volume = 0.8;
    this.loops = {};
    this.voices = new Map();
  }

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const ctx = this.ctx = new (window.AudioContext || window.webkitAudioContext)();
    this.master = ctx.createGain();
    this.master.gain.value = this.volume;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -14; comp.ratio.value = 5;
    this.master.connect(comp); comp.connect(ctx.destination);
    this.sfx = ctx.createGain(); this.sfx.connect(this.master);
    this.music = ctx.createGain(); this.music.gain.value = 0.5; this.music.connect(this.master);
    // Reverb send (used inside the facility)
    this.verb = ctx.createConvolver();
    this.verb.buffer = this._impulse(2.6, 2.2);
